def solve(inputs: dict) -> float:
    M = inputs['M']
    p = inputs.get('power', inputs.get('POWER', 37))
    mod = inputs.get('mod', inputs.get('MOD', None))
    # try to find modulus and power from inputs generically
    # fallback to known keys
    if mod is None:
        for k in inputs:
            if 'mod' in k.lower():
                mod = inputs[k]
    if isinstance(p, dict):
        pass
    a, b = M[0]
    c, d = M[1]
    # result identity
    R = [[1, 0], [0, 1]]
    base = [[a % mod, b % mod], [c % mod, d % mod]]
    def matmul(X, Y):
        return [[(X[0][0]*Y[0][0]+X[0][1]*Y[1][0]) % mod,
                 (X[0][0]*Y[0][1]+X[0][1]*Y[1][1]) % mod],
                [(X[1][0]*Y[0][0]+X[1][1]*Y[1][0]) % mod,
                 (X[1][0]*Y[0][1]+X[1][1]*Y[1][1]) % mod]]
    e = p
    while e > 0:
        if e & 1:
            R = matmul(R, base)
        base = matmul(base, base)
        e >>= 1
    return float((R[0][0] + R[0][1] + R[1][0] + R[1][1]) % mod)

